package org.acme;
@Service
public class TaskService {
  private final TaskEntityRepository repository;
  public TaskEntity getScoped(Long id, Long currentOrgId) {
    TaskEntity entity = repository.findById(id).orElse(null);
    if (entity != null && !entity.getOrganizationId().equals(currentOrgId)) { return null; }
    return entity;
  }
}

